themeCss:
body.theme-bento-grid {
    --page-bg: #f7f7f5;
    --page-bg-gradient: none;
    --text-color: #31353d;
    --heading-color: #14171c;
    --link-color: #2b66dc;
    --border-color: #e3e4e1;
    --card-bg: #ffffff;
    --card-shadow: none;
    --card-hover-shadow: 0 6px 18px -12px rgba(20, 23, 28, .4);
    --header-bg: #14171c;
    --header-text-color: #f7f7f5;
    --prompt-bg: #f1f2ef;
    --prompt-text-color: #3c414a;
    --button-bg: #14171c;
    --button-text-color: #ffffff;
    --button-hover-bg: #31353d;
    --card-border-radius: 16px;
    --base-font: var(--font-inter);
    --heading-font: var(--font-inter);
}

cardCss:
/* Styles for Bento Grid Card */
.card[data-style-id="bento-grid"] { background-color: #ffffff; border: 1px solid #e3e4e1; border-radius: 16px; box-shadow: none; }
.card[data-style-id="bento-grid"] h3 { color: #14171c; letter-spacing: -0.02em; }
.card[data-style-id="bento-grid"] .prompt-text { background-color: #f1f2ef; color: #3c414a; border-radius: 10px; }
.card[data-style-id="bento-grid"] .btn { border-radius: 10px; }
.card[data-style-id="bento-grid"] .btn:not(.btn-secondary) { background-color: #14171c; color: #ffffff !important; }
.card[data-style-id="bento-grid"] .btn-secondary { background-color: #f1f2ef; color: #14171c !important; }
.card[data-style-id="bento-grid"]:hover { border-color: #c9cbc6; }

themeCss:
body.theme-liquid-glass {
    --page-bg: #0b1020;
    --page-bg-gradient: radial-gradient(circle at 25% 10%, #2b3fa0, transparent 55%), radial-gradient(circle at 80% 80%, #7a2f9e, transparent 55%);
    --text-color: #e8eefc;
    --heading-color: #ffffff;
    --link-color: #9fc2ff;
    --border-color: rgba(255, 255, 255, .28);
    --card-bg: rgba(255, 255, 255, .10);
    --card-shadow: inset 0 1px 0 rgba(255, 255, 255, .55);
    --card-hover-shadow: inset 0 1px 0 rgba(255, 255, 255, .7), 0 10px 30px -18px rgba(0, 0, 0, .8);
    --header-bg: rgba(11, 16, 32, .55);
    --header-text-color: #ffffff;
    --prompt-bg: rgba(255, 255, 255, .12);
    --prompt-text-color: #dbe6ff;
    --button-bg: rgba(255, 255, 255, .92);
    --button-text-color: #0b1020;
    --button-hover-bg: #ffffff;
    --card-border-radius: 24px;
    --base-font: var(--font-inter);
    --heading-font: var(--font-inter);
}

cardCss:
/* Styles for Liquid Glass Card */
.card[data-style-id="liquid-glass"] { background-color: rgba(255, 255, 255, .09); border: 1px solid rgba(255, 255, 255, .30); border-radius: 24px; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55); backdrop-filter: blur(20px) saturate(160%); -webkit-backdrop-filter: blur(20px) saturate(160%); }
.card[data-style-id="liquid-glass"] h3 { color: #ffffff; }
.card[data-style-id="liquid-glass"] .prompt-text { background-color: rgba(255, 255, 255, .12); color: #dbe6ff; border-radius: 12px; }
.card[data-style-id="liquid-glass"] .btn { border-radius: 999px; }
.card[data-style-id="liquid-glass"] .btn:not(.btn-secondary) { background-color: rgba(255, 255, 255, .92); color: #0b1020 !important; }
.card[data-style-id="liquid-glass"] .btn-secondary { background-color: rgba(255, 255, 255, .14); color: #e8eefc !important; }
.card[data-style-id="liquid-glass"]:hover { background-color: rgba(255, 255, 255, .15); }

themeCss:
body.theme-editorial {
    --page-bg: #fbfaf7;
    --page-bg-gradient: none;
    --text-color: #2b2a27;
    --heading-color: #14130f;
    --link-color: #8a2f1d;
    --border-color: #ded9cf;
    --card-bg: transparent;
    --card-shadow: none;
    --card-hover-shadow: none;
    --header-bg: #fbfaf7;
    --header-text-color: #14130f;
    --prompt-bg: #f2efe8;
    --prompt-text-color: #3a3833;
    --button-bg: #14130f;
    --button-text-color: #fbfaf7;
    --button-hover-bg: #8a2f1d;
    --card-border-radius: 0;
    --base-font: var(--font-lato);
    --heading-font: var(--font-serif);
}

cardCss:
/* Styles for Editorial Card */
.card[data-style-id="editorial"] { background-color: #fbfaf7; border: none; border-top: 2px solid #14130f; border-radius: 0; box-shadow: none; }
.card[data-style-id="editorial"] h3 { font-family: var(--font-serif); color: #14130f; font-weight: 700; }
.card[data-style-id="editorial"] .prompt-text { background-color: #f2efe8; color: #3a3833; border-radius: 0; font-family: var(--font-lato); }
.card[data-style-id="editorial"] .btn { border-radius: 0; }
.card[data-style-id="editorial"] .btn:not(.btn-secondary) { background-color: #14130f; color: #fbfaf7 !important; }
.card[data-style-id="editorial"] .btn-secondary { background-color: transparent; color: #8a2f1d !important; border: 1px solid #ded9cf; }
.card[data-style-id="editorial"]:hover { border-top-color: #8a2f1d; }

/* Styles for Neo-Brutalism Card */
.card[data-style-id="neo-brutalism"] { background-color: #ffffff; border: 3px solid #000000; border-radius: 0; box-shadow: 8px 8px 0 #000000; }
.card[data-style-id="neo-brutalism"] h3 { font-family: var(--font-montserrat); color: #000000; text-transform: uppercase; letter-spacing: -0.01em; }
.card[data-style-id="neo-brutalism"] .prompt-text { background-color: #ffe08a; color: #000000; border-radius: 0; }
.card[data-style-id="neo-brutalism"] .btn { border: 3px solid #000000; border-radius: 0; font-weight: 700; }
.card[data-style-id="neo-brutalism"] .btn:not(.btn-secondary) { background-color: #c9b8ff; color: #000000 !important; }
.card[data-style-id="neo-brutalism"] .btn-secondary { background-color: #ffffff; color: #000000 !important; }
.card[data-style-id="neo-brutalism"]:hover { transform: translate(4px, 4px); box-shadow: 4px 4px 0 #000000; }

themeCss:
body.theme-neo-swiss {
    --page-bg: #ffffff;
    --page-bg-gradient: none;
    --text-color: #1a1a1a;
    --heading-color: #000000;
    --link-color: #e2001a;
    --border-color: #d6d6d6;
    --card-bg: #ffffff;
    --card-shadow: none;
    --card-hover-shadow: none;
    --header-bg: #ffffff;
    --header-text-color: #000000;
    --prompt-bg: #f4f4f4;
    --prompt-text-color: #1a1a1a;
    --button-bg: #000000;
    --button-text-color: #ffffff;
    --button-hover-bg: #e2001a;
    --card-border-radius: 0;
    --base-font: var(--font-helvetica);
    --heading-font: var(--font-helvetica);
}

cardCss:
/* Styles for Neo-Swiss Card */
.card[data-style-id="neo-swiss"] { background-color: #ffffff; border: none; border-top: 2px solid #000000; border-radius: 0; box-shadow: none; }
.card[data-style-id="neo-swiss"] h3 { font-family: var(--font-helvetica); color: #000000; letter-spacing: -0.03em; }
.card[data-style-id="neo-swiss"] .prompt-text { background-color: #f4f4f4; color: #1a1a1a; border-radius: 0; }
.card[data-style-id="neo-swiss"] .btn { border-radius: 0; }
.card[data-style-id="neo-swiss"] .btn:not(.btn-secondary) { background-color: #000000; color: #ffffff !important; }
.card[data-style-id="neo-swiss"] .btn-secondary { background-color: transparent; color: #000000 !important; border: 1px solid #000000; }
.card[data-style-id="neo-swiss"]:hover { border-top-color: #e2001a; }

/* Styles for Acid Graphics Card */
.card[data-style-id="acid-graphics"] { background-color: #131313; border: 1px solid #2a2a2a; border-radius: 2px; box-shadow: 4px 4px 0 #c6ff00; }
.card[data-style-id="acid-graphics"] h3 { font-family: var(--font-inter); color: #c6ff00; text-transform: uppercase; letter-spacing: -0.04em; }
.card[data-style-id="acid-graphics"] .prompt-text { background-color: #1c1c1c; color: #eaeaea; border-radius: 0; font-family: var(--font-space-mono); }
.card[data-style-id="acid-graphics"] .btn { border-radius: 2px; font-family: var(--font-space-mono); }
.card[data-style-id="acid-graphics"] .btn:not(.btn-secondary) { background-color: #c6ff00; color: #0a0a0a !important; }
.card[data-style-id="acid-graphics"] .btn-secondary { background-color: #1c1c1c; color: #ff2bd1 !important; border: 1px solid #ff2bd1; }
.card[data-style-id="acid-graphics"]:hover { box-shadow: 4px 4px 0 #ff2bd1; }
